            & = \frac{{P}_\mathsf{coor}(x_+ \mathrel{\vert}x) \prod_j P(x_-^{(j)}) }{{P}_\mathsf{coor}(x_+ \mathrel{\vert}x) \prod_j P(x_-^{(j)})  + \sum_i {P}_\mathsf{coor}(x_-^{(i)} \mathrel{\vert}x) P(x_+) \prod_{j \neq i} P(x_-^{(j)})} \tag{27}\\
            & = \frac{{P}_\mathsf{coor}(x_+ \mathrel{\vert}x) / P(x_+) }{{P}_\mathsf{coor}(x_+ \mathrel{\vert}x) / P(x_+) + \sum_i {P}_\mathsf{coor}(x_-^{(i)} \mathrel{\vert}x) / P(x_-^{(i)})}. \tag{28}\end{align*}$$
